package vn.edu.hunre.nhom11.carrental.content.api;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import vn.edu.hunre.nhom11.carrental.content.domain.News;import vn.edu.hunre.nhom11.carrental.content.repository.NewsRepository;import vn.edu.hunre.nhom11.carrental.shared.exception.ApiException;@RestController@RequestMapping("/api/news")public class NewsController{private final NewsRepository news;public NewsController(NewsRepository n){news=n;}@GetMapping Object all(){return news.findByPublishedTrueOrderByCreatedAtDesc();}@GetMapping("/{id}")Object one(@PathVariable Long id){return news.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Không tìm thấy tin tức"));}@PostMapping@PreAuthorize("hasRole('ADMIN')")ResponseEntity<?>create(@RequestBody News n){return ResponseEntity.status(201).body(news.save(n));}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")Object update(@PathVariable Long id,@RequestBody News n){n.setId(id);return news.save(n);}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")ResponseEntity<?>delete(@PathVariable Long id){news.deleteById(id);return ResponseEntity.noContent().build();}}

